doc.core_properties.title='مشخصات جامع نیازمندی‌های نرم‌افزار Nexora'
doc.core_properties.subject='SRS نسخه ۳'
doc.core_properties.author='Nexora'

def p(text='',style=None):
    return doc.add_paragraph(text,style)

sections=[]
requirements=[]
def heading(title):
    idx=len(sections)+1
    para=doc.add_heading(title,1)
    tag=f'section_{idx}'
    start=OxmlElement('w:bookmarkStart'); start.set(qn('w:id'),str(idx)); start.set(qn('w:name'),tag)
    end=OxmlElement('w:bookmarkEnd'); end.set(qn('w:id'),str(idx))
    para._p.insert(0,start); para._p.append(end)
    sections.append((title,tag))

def table(headers,rows,widths=None):
    t=doc.add_table(rows=1,cols=len(headers)); t.autofit=False
    pr=t._tbl.tblPr
    bidi=OxmlElement('w:bidiVisual'); pr.append(bidi)
    borders=OxmlElement('w:tblBorders')
    for edge in ['top','left','bottom','right','insideH','insideV']:
        e=OxmlElement('w:'+edge); e.set(qn('w:val'),'single'); e.set(qn('w:sz'),'4'); e.set(qn('w:color'),'D9D9D9'); borders.append(e)
    pr.append(borders)
    margins=OxmlElement('w:tblCellMar')
    for edge in ['top','bottom','left','right']:
        e=OxmlElement('w:'+edge); e.set(qn('w:w'),'95'); e.set(qn('w:type'),'dxa'); margins.append(e)
    pr.append(margins)
    for i,h in enumerate(headers):t.rows[0].cells[i].text=h
    t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
    for row in rows:
        cells=t.add_row().cells
        for i,value in enumerate(row): cells[i].text=str(value)
    for ri,row in enumerate(t.rows):
        row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
        for ci,cell in enumerate(row.cells):
            cell.width=Cm((widths or [16.8/len(headers)]*len(headers))[ci])
            if ri==0:
                sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E8EEF5'); cell._tc.get_or_add_tcPr().append(sh)
            for para in cell.paragraphs:
                para.paragraph_format.space_after=Pt(3)
                for run in para.runs:run.font.size=Pt(9);run.bold=ri==0
    p()

def reqs(prefix,source,body,priority='ضروری',status='مبنای پذیرش'):
    for number,line in enumerate(body.strip().splitlines(),1):
        title,statement,accept=line.split('|')
        rid=f'{prefix}-{number:02d}'
        doc.add_heading(f'{rid}  {title}',2)
        p(statement)
        para=p('معیار پذیرش: '+accept)
        para.paragraph_format.space_after=Pt(4)
        meta=p(f'اولویت: {priority} | وضعیت: {status} | مرجع: {source} | آزمون: AT-{rid}')
        for r in meta.runs:r.font.size=Pt(8)
        requirements.append((rid,title,source,status))

