table(['موجودیت','داده لازم و ارتباط'],[['سازمان و کاربر','شناسه پایدار، نقش، وضعیت، زمان ایجاد و تعلق سازمانی'],['نشست','مالک، انقضا، شناسه قابل ابطال و زمان ابطال'],['مجموعه دانش','نام، توضیح، سازمان و مجوزهای منابع'],['سند','نام اصلی، نوع، اندازه، مسیر امن، وضعیت و نسخه پردازش'],['کار پردازش','سند، درخواست‌کننده، تلاش‌ها، Lease، heartbeat و خطا'],['قطعه','سند و نسخه، متن، والد، صفحه در صورت وجود و بردار'],['گفتگو و پیام','مالک، ترتیب، متن، زمان، منابع و تنظیمات مؤثر'],['دستیار','دستور، مدل، حالت پاسخ، وضعیت و مجموعه‌های مرتبط'],['Connector و sync','نوع، مقصد، ارجاع راز، برنامه، Lease و نتیجه'],['بازخورد و اشتراک','پاسخ یا snapshot مرتبط، مالک، دامنه و ابطال'],['اعلان','کاربر، سازمان، رخداد، شدت، هدف و زمان خواندن']],[4,12.8])
reqs('DAT','C01 و C06', '''شناسه پایدار|هر موجودیت عملیاتی باید شناسه پایدار مستقل از نام نمایشی داشته باشد.|تغییر نام فایل، مجموعه یا گفتگو روابط داده را قطع نکند.
زمان مرجع|زمان‌ها باید با مبنای زمانی روشن ذخیره و فقط هنگام نمایش بومی‌سازی شوند.|تبدیل زبان تاریخ ذخیره‌شده یا ترتیب زمانی رخدادها را تغییر ندهد؛ روز گزارش با منطقه زمانی مصوب محاسبه شود.
سازگاری رابطه‌ها|ارتباط پیام، منبع، سند و سازمان باید در ایجاد و خواندن بررسی شود.|ایجاد رابطه میان دو سازمان یا قطعه بدون سند معتبر رد شود.
نسخه پردازش|بازپردازش باید نسخه محتوای مورد استفاده در پاسخ را قابل ردیابی کند.|پس از بازپردازش، پاسخ قدیمی با قطعه جدید به اشتباه بازنویسی نشود و عدم دسترسی احتمالی صریح باشد.
پاک‌سازی هماهنگ|حذف باید تکلیف رکورد، فایل، بردار، اشتراک و اعلان مرتبط را مشخص کند.|پس از حذف نهایی، جست‌وجو یا پیوند قدیمی محتوای حذف‌شده را بازنگرداند؛ خطای پاک‌سازی قابل retry باشد.
نگهداری داده|مدت نگهداری اسناد، گفتگوها، رویدادها و نسخه پشتیبان باید به تفکیک سازمان و سیاست مشخص شود.|اجرای پاک‌سازی فقط بر داده خارج از مدت مصوب اثر بگذارد و تصمیم‌های باز بخش ۲۷ پیش از تولید تعیین شوند.''')
p('چرخه سند از دریافت و قرنطینه آغاز می‌شود. پس از پذیرش، سند در صف قرار می‌گیرد؛ سپس استخراج، OCR در صورت نیاز، قطعه‌بندی و ایندکس انجام می‌شود. انتهای موفق indexed است. رد امنیتی قبل از پذیرش و failed پس از خطای پردازش دو وضعیت معنایی متفاوت‌اند و نباید با یک پیام کلی ادغام شوند.')
table(['وضعیت مفهومی','رخداد خروج','رفتار مورد انتظار'],[['قرنطینه','تأیید پاک یا رد','قبل از تأیید هیچ استخراجی انجام نشود'],['صف','تصاحب Worker','انتظار با شناسه کار قابل پیگیری باشد'],['پردازش','تکمیل یا خطا','مرحله و heartbeat به‌روز شوند'],['آماده','حذف یا بازپردازش','فقط نسخه معتبر در بازیابی استفاده شود'],['ناموفق','retry یا حذف','دلیل و تعداد تلاش حفظ شوند'],['لغوشده یا حذف‌شده','پاک‌سازی','نتیجه دیررس دوباره قابل دسترسی نشود']],[4,4.5,8.3])

heading('۲۱ قرارداد رابط‌ها و خطاها')
p('REST API زیر /api/v1 قرارداد نسخه‌بندی‌شده رابط است. طرح دقیق فیلدها باید از OpenAPI همان نسخه استخراج شود؛ این سند خانواده‌های رابط و معنای رفتار را تثبیت می‌کند. پاسخ خطا باید کد قابل دسته‌بندی و پیام امن داشته باشد و برای پیگیری عملیاتی بتوان آن را به شناسه درخواست مرتبط کرد.')
table(['خانواده رابط','وظیفه','قرارداد خطا'],[['auth و users','ورود، خروج، تغییر رمز و اعضا','عدم احراز هویت، دسترسی و ورودی نامعتبر'],['document sets و documents','مجموعه، فایل، وضعیت و retry','نوع، حجم، بدافزار و اسکنر ناموجود'],['conversations و rag و research','گفتگو، بازیابی و پاسخ','منبع نامجاز، timeout و خطای مدل'],['connectors','ثبت، sync و Webhook','اعتبارنامه، مقصد ممنوع و شکست جزئی'],['chat shares و feedback','اشتراک و بازخورد','token نامعتبر، ابطال یا مالک نامجاز'],['analytics و notifications','گزارش و اعلان','سازمان یا کاربر نامجاز'],['health و ready و metrics','سلامت و مشاهده‌پذیری','عدم آمادگی یا مجوز متریک']],[5,6,5.8])
table(['کد متعارف','معنا و واکنش رابط'],[['400 یا 422','ورودی یا فایل ردشده؛ پیام مشخص و اصلاح ورودی'],['401','نشست نامعتبر؛ ورود دوباره بدون افشای داده'],['403 یا 404','منبع غیرمجاز یا ناموجود طبق سیاست عدم افشا'],['413','حجم بیش از سقف؛ نمایش حد مجاز'],['415','نوع محتوای پشتیبانی‌نشده یا نامنطبق'],['429','محدودیت نرخ؛ رعایت زمان تلاش مجدد اعلام‌شده'],['503','وابستگی ضروری موقتاً در دسترس نیست؛ موفقیت اعلام نشود'],['خطای شبکه یا timeout','حفظ ورودی، پایان انتظار و تلاش مجدد کنترل‌شده']],[3,13.8])
p('در تعامل خارجی، timeout اتصال و پاسخ باید محدود باشند؛ retry فقط برای خطای موقت و با توجه به تکرارپذیری امن عملیات انجام شود. تکرار خودکار ساخت کار یا انتشار پیوند بدون شناسه یکتا می‌تواند اثر مضاعف ایجاد کند و باید در قرارداد API مهار شود.')

heading('۲۲ امنیت و حریم اطلاعات')
reqs('SEC','C01 و C05 و U', '''مجوز در همه لایه‌ها|کنترل مجوز باید در API، سرویس، بازیابی و دریافت فایل اعمال شود.|دورزدن رابط یا تغییر شناسه هیچ مسیر جایگزین افشای داده ایجاد نکند.
حفاظت انتقال|ارتباط تولید باید از TLS معتبر استفاده کند و تنظیمات ناامن فقط به محیط آزمون محدود شوند.|پیکربندی تولید با کوکی ناامن یا اسکن غیرفعال پذیرفته نشود.
حفاظت مرورگر|CORS، درخواست‌های تغییردهنده و محتوای Markdown باید در برابر درخواست ناخواسته و اجرای کد کنترل شوند.|مبدأ نامجاز نتواند عملیات حساس با نشست کاربر اجرا کند و متن مدل یا سند اسکریپت اجرا نکند.
حداقل داده خارجی|ارسال به مدل و OCR باید به داده مورد نیاز و ارائه‌دهنده مصوب محدود شود.|آزمون درخواست خروجی هیچ سند خارج از دامنه یا راز سرویس در payload نداشته باشد.
حفاظت رازها|رازها باید از تنظیمات عمومی، مخزن کد و پاسخ خطا جدا باشند و امکان چرخش داشته باشند.|چرخش کلید بدون بازنویسی سند کاربر انجام شود و گزارش‌ها مقدار قبل یا بعد را آشکار نکنند.
ثبت عملیات حساس|ورود ناموفق، تغییر رمز، تغییر مجوز، حذف و رد امنیتی فایل باید قابل ردیابی باشند.|رویداد دارای زمان، عامل، سازمان، هدف و نتیجه باشد و رمز یا متن کامل سند در آن ثبت نشود.
محدودیت مصرف|بارگذاری، ورود، پرسش و اتصال خارجی باید محدودیت نرخ یا بودجه مناسب داشته باشند.|کاربر پرمصرف به حلقه درخواست نامحدود نرسد و خطای محدودیت با خطای داخلی اشتباه نشود.
آزمون مرز داده|نسخه انتشار باید آزمون منفی حداقل دو سازمان و چند سطح مجوز را بگذراند.|تمام مسیرهای سند، منبع، گفتگو، اشتراک، اعلان و اعضا با شناسه سازمان دیگر بررسی و نتیجه ثبت شوند.''')

heading('۲۳ پایداری پایش و بازیابی')
reqs('OPS','C16 و U', '''زنده‌بودن فرایند|liveness باید زنده‌بودن فرایند را بدون ایجاد یا حذف داده بررسی کند.|فراخوانی مکرر health تعداد collection، سند و فایل را تغییر ندهد.
آمادگی سرویس|readiness باید وابستگی‌های ضروری و تازگی Workerها را با timeout محدود بررسی کند.|قطع PostgreSQL یا Qdrant یا heartbeat منقضی پاسخ 503 بدهد؛ health فرایند زنده لزوماً شکست نخورد.
متریک‌های عملیاتی|مدت پردازش، طول صف، خطای OCR و مدل، مصرف API و شکست sync باید قابل مشاهده باشند.|با رخداد نمونه شمارنده یا اندازه‌گیری مرتبط تغییر کند و برچسب‌ها متن محرمانه یا تنوع نامحدود نداشته باشند.
دسترسی متریک|متریک داخلی باید با مجوز مشخص محافظت شود و در نبود تنظیم امنیتی عمومی نشود.|درخواست بدون اعتبار به جزئیات متریک دسترسی نگیرد.
گزارش مرکزی|log سرویس‌ها باید با شناسه درخواست یا job و قالب قابل جمع‌آوری ثبت شود.|خطای سند از API تا Worker قابل دنبال‌کردن باشد؛ وجود log محلی به تنهایی معادل راه‌اندازی سامانه مرکزی تلقی نشود.
پشتیبان هماهنگ|پشتیبان باید PostgreSQL، فایل‌ها و اطلاعات لازم برای بازسازی بردار و تنظیمات را پوشش دهد.|بازیابی در محیط جدا بتواند سند، مجوز و منبع پاسخ را به هم متصل کند و رازها جداگانه محافظت شوند.
آزمون بازیابی|بازیابی باید با نسخه پشتیبان واقعی در محیط جدا تمرین و زمان و داده ازدست‌رفته ثبت شود.|صرف موفقیت backup معیار قبولی نباشد؛ ورود، خواندن سند و پاسخ مستند بعد از restore بررسی شوند.
ارتقای نسخه|مهاجرت داده و استقرار باید پیش‌نیاز، ترتیب اجرا و مسیر بازگشت مشخص داشته باشند.|شکست migration ترافیک را به نسخه ناسازگار هدایت نکند و بازگشت با بازیابی داده قابل تمرین باشد.
کنترل مصرف منابع|Worker و scheduler باید هم‌زمانی و polling محدود داشته باشند و build یا آزمون سنگین بخشی از استفاده عادی نباشد.|در حالت بیکار حلقه پرمصرف وجود نداشته باشد؛ تعداد کار هم‌زمان از تنظیم مصوب تجاوز نکند.''')

